         <KanbanColumn ColumnName="In Progress"
                       Tasks="@FilteredTasks(StatusInProgress)"
                       ShowMoveLeft="true"
                       ShowMoveRight="true"
                       OnMoveLeft="@(id => MoveTask(id, StatusToDo))"
                       OnMoveRight="@(id => MoveTask(id, StatusDone))"
                       OnAddTask="@(data => AddTask(data, StatusInProgress))" />

         <KanbanColumn ColumnName="Done"
                       Tasks="@FilteredTasks(StatusDone)"
                       ShowMoveLeft="true"
                       ShowMoveRight="false"
                       OnMoveLeft="@(id => MoveTask(id, StatusInProgress))"
                       OnAddTask="@(data => AddTask(data, StatusDone))" />
     </div>
 }

 @code {
     private const string StatusToDo = "To Do";
     private const string StatusInProgress = "In Progress";
     private const string StatusDone = "Done";

     private List<TaskItem> allTasks = new();
     private string searchText = string.Empty;
     private bool loading = true;
     private string? errorMessage;

     protected override async Task OnInitializedAsync()
     {
         await LoadTasks();
     }

     private async Task LoadTasks()
     {
         loading = true;
         errorMessage = null;
         try
         {
             allTasks = await TaskService.GetAllTasksAsync();
         }
         catch (Exception ex)
         {
             errorMessage = $"Failed to load tasks: {ex.Message}";
         }
         finally
         {
             loading = false;
         }
     }

     private void OnSearchChanged(string text)
     {
         searchText = text;
     }

     private List<TaskItem> FilteredTasks(string status)
     {
         var tasks = allTasks.Where(t => t.Status == status);
         if (!string.IsNullOrWhiteSpace(searchText))
         {
             tasks = tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
         }
         return tasks.ToList();
     }

     private async Task MoveTask(int taskId, string newStatus)
     {
         try
         {
             await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
             var index = allTasks.FindIndex(t => t.Id == taskId);
             if (index >= 0)
             {
                 allTasks[index] = allTasks[index] with { Status = newStatus };
             }
         }
         catch (Exception ex)
         {
             errorMessage = $"Failed to move task: {ex.Message}";
         }
     }

     private async Task AddTask((string Title, string Assignee, string Priority, DateTime DueDate) data, string status)
     {
         try
         {
             var newTask = await TaskService.CreateTaskAsync(data.Title, data.Assignee, data.Priority, data.DueDate);
             allTasks.Add(newTask with { Status = status });
         }
         catch (Exception ex)
         {
             errorMessage = $"Failed to create task: {ex.Message}";
         }
     }
 }

